use vstd::prelude::*;

verus! {
    // Specification for checking if a character is a digit
    spec fn is_digit(c: char) -> bool {
        c >= '0' && c <= '9'
    }

    // Function to check if all characters in the vector are digits
    fn is_integer(text: &Vec<char>) -> (result: bool)
        ensures
            result == (forall |i: nat| (i < text.len() as nat) ==> is_digit(text[i])),
    {
        let mut i: nat = 0;
        let len = text.len() as nat;

        // If the vector is empty, return true
        if len == 0 {
            return true;
        }

        // Iterate through the characters in the vector
        while i < len
            invariant
                0 <= i <= len,
                forall |j: nat| (j < i) ==> is_digit(text[j]),
        {
            // Check if the current character is a digit
            if !is_digit(text[i]) {
                return false; // If any character is not a digit, return false
            }
            i = i + 1; // Move to the next character
        }
        true // If all characters are digits, return true
    }
}

